      SUBROUTINE JOSTLE(M)CC     CALCULATES CONTRIBUTION OF FIXED MISALIGNMENT TO MISALIGNMENTC     TABLECC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM2B.CIN'      INCLUDE 'ELM7B.CIN'      INCLUDE 'ELM8H.CIN'      INCLUDE 'ELM8M.CIN'      INCLUDE 'ELM8J.CIN'      INCLUDE 'R.CIN'      INCLUDE 'RC2.CIN'      INCLUDE 'R2P.CIN'      INCLUDE 'SI.CIN'CC     LOCAL VARIABLESC      INTEGER         M      REAL            FOOD(6), WORK(6,6)CC---------------------------------------------------------------------      IF (.NOT. BEFORE) GO TO 100CC     MISALIGNMENT CENTROIDC      DO 20 J = 1, 6      COM(J,M,NM) = COD(J)   20 CONTINUECC     MISALIGNMENT TRANSFER MATRIXC      IF (R2PM(NM)) GO TO 70      IF (R2P) GO TO 30      L1L2 = 0      DO 25 L2 = 1, 6      DO 25 L1 = 1, 6      L1L2 = L1L2 + 1      RC2M(L1L2,M,NM) =  R(L1,L2)   25 CONTINUE      GO TO 50C   30 DO 40 L1 = 1, 6      DO 40 L2 = 1, 6      S = 0.0      DO 35 L3 = 1, 6      S = S + R(L1,L3)*RC2(L3,L2)   35 CONTINUE      WORK(L1,L2) = S   40 CONTINUEC      L1L2 = 0      DO 45 L2 = 1, 6      DO 45 L1 = 1, 6      L1L2 = L1L2 + 1      RC2M(L1L2,M,NM) = WORK(L1,L2)   45 CONTINUEC   50 L1L2 = 0      DO 60 L1 = 1, 6      DO 60 L2 = 1, 6      L1L2 = L1L2 + 1      SIM(L1L2,M,NM) = SI(L1,L2)   60 CONTINUEC      GO TO 200C   70 DO 80 L1 = 1, 6      L3L2 = 0      DO 80 L2 = 1, 6      S = 0.0      DO 75 L3 = 1, 6      L3L2 = L3L2 + 1      S = S + R(L1,L3)*RC2M(L3L2,M,NM)   75 CONTINUE      WORK(L1,L2) = S   80 CONTINUEC      L1L2 = 0      DO 90 L2 = 1, 6      DO 90 L1 = 1, 6      L1L2 = L1L2 + 1      RC2M(L1L2,M,NM) = WORK(L1,L2)   90 CONTINUE      GO TO 200CC     MISALIGNMENT CENTROIDC  100 DO 120 J = 1, 6      SS = 0.0      DO 110 K = 1, 6      SS = SS + R(J,K)*COM(K,M,NM)  110 CONTINUE      FOOD(J) = SS  120 CONTINUEC      DO 130 J = 1, 6      COM(J,M,NM) = FOOD(J)  130 CONTINUEC      DO 160 J = 1, 6      COM(J,M,NM) = COM(J,M,NM) + COD(J)  160 CONTINUECC     MISALIGNMENT TRANSFER MATRIXC      DO 180 L1 = 1, 6      L3L2 = 0      DO 180 L2 = 1, 6      S = 0.0      DO 175 L3 = 1, 6      L3L2 = L3L2 + 1      S = S + R(L1,L3)*RC2M(L3L2,M,NM)  175 CONTINUE      WORK(L1,L2) = S  180 CONTINUEC      L1L2 = 0      DO 190 L2 = 1, 6      DO 190 L1 = 1, 6      L1L2 = L1L2 + 1      RC2M(L1L2,M,NM) = WORK(L1,L2)  190 CONTINUEC  200 RETURN      END